/**
 * Arithmetic in the Galois field GF(2^8) used by QR Code, and the
 * Reed-Solomon error-correction encoder built on top of it.
 *
 * The field is generated by the primitive polynomial
 * x^8 + x^4 + x^3 + x^2 + 1 (0x11D) with alpha = 2.
 */

const PRIMITIVE_POLYNOMIAL = 0x11d;

/** EXP[i] = alpha^i, doubled in length so products never need a modulo. */
const EXP = new Uint8Array(512);
/** LOG[v] = i such that alpha^i = v (LOG[0] is undefined and unused). */
const LOG = new Uint8Array(256);

function buildTables() {
  let value = 1;
  for (let power = 0; power < 255; power++) {
    EXP[power] = value;
    LOG[value] = power;
    value <<= 1;
    if (value & 0x100) value ^= PRIMITIVE_POLYNOMIAL;
  }
  for (let power = 255; power < EXP.length; power++) EXP[power] = EXP[power - 255];
}

buildTables();

/**
 * alpha raised to a power.
 * @param {number} power any non-negative integer (taken modulo 255)
 * @returns {number} field element 1..255
 */
export function gfExp(power) {
  return EXP[power % 255];
}

/**
 * Discrete logarithm of a non-zero field element.
 * @param {number} value field element 1..255
 * @returns {number} power 0..254 with alpha^power = value
 */
export function gfLog(value) {
  if (value < 1 || value > 255) throw new RangeError(`log is undefined for ${value}`);
  return LOG[value];
}

/**
 * Multiplies two field elements.
 * @param {number} a 0..255
 * @param {number} b 0..255
 * @returns {number} product 0..255
 */
export function gfMultiply(a, b) {
  if (a === 0 || b === 0) return 0;
  return EXP[LOG[a] + LOG[b]];
}

const generatorCache = new Map();

/**
 * Reed-Solomon generator polynomial (x - alpha^0)(x - alpha^1)...(x - alpha^(degree-1)).
 * @param {number} degree number of error-correction codewords (1..30 in QR Code)
 * @returns {Uint8Array} degree + 1 coefficients, highest power first (leading 1)
 */
export function rsGeneratorPoly(degree) {
  if (!generatorCache.has(degree)) {
    let poly = Uint8Array.of(1);
    for (let i = 0; i < degree; i++) {
      const next = new Uint8Array(poly.length + 1);
      const root = gfExp(i);
      poly.forEach((coefficient, j) => {
        next[j] ^= coefficient;
        next[j + 1] ^= gfMultiply(coefficient, root);
      });
      poly = next;
    }
    generatorCache.set(degree, poly);
  }
  return generatorCache.get(degree);
}

/**
 * Error-correction codewords for one block: the remainder of
 * data(x) * x^degree divided by the generator polynomial.
 * @param {Iterable<number>} data data codewords of the block
 * @param {number} degree number of error-correction codewords
 * @returns {Uint8Array} the error-correction codewords
 */
export function rsRemainder(data, degree) {
  const generator = rsGeneratorPoly(degree);
  const remainder = new Uint8Array(degree);
  for (const codeword of data) {
    const factor = codeword ^ remainder[0];
    remainder.copyWithin(0, 1);
    remainder[degree - 1] = 0;
    for (let i = 0; i < degree; i++) remainder[i] ^= gfMultiply(generator[i + 1], factor);
  }
  return remainder;
}
